// Interface preferences are separate from the financial ledger.
export const LANGUAGE_KEY='flex-language-v1';
export function readLanguage(storage=globalThis.localStorage){try{const value=storage?.getItem(LANGUAGE_KEY);return ['en','fr'].includes(value)?value:'en';}catch{return 'en';}}
let language=readLanguage();
export const getLanguage=()=>language;
export const getLocale=()=>language==='fr'?'fr-FR':'en-GB';
export function setLanguage(value,storage=globalThis.localStorage){if(!['fr','en'].includes(value))return false;language=value;try{storage?.setItem(LANGUAGE_KEY,value);}catch{}return true;}
