const dictionaries={en:new Map(),fr:new Map()};
for(const [en,fr] of pairs){for(const key of [en,fr]){dictionaries.en.set(key,en);dictionaries.fr.set(key,fr);}}
export function tr(value,lang=language){
 const text=String(value??''),target=lang==='fr'?'fr':'en';
 if(dictionaries[target].has(text))return dictionaries[target].get(text);
 const stay=text.match(/^(?:Séjour|Stay) (\d+)$/);
 if(stay)return (target==='fr'?'Séjour ':'Stay ')+stay[1];
 const count=text.match(/^(\d+) (?:transactions?|opérations?)$/);
 if(count)return count[1]+' '+(target==='fr'?'opération':'transaction')+(Number(count[1])===1?'':'s');
 const personal=text.match(/^(?:Personal|Personnel) · ([A-Z]{3})$/);
 if(personal)return (target==='fr'?'Personnel':'Personal')+' · '+personal[1];
 const balance=text.match(/^(?:Solde du compte|Account balance) ([A-Z]{3})$/);
 if(balance)return (target==='fr'?'Solde du compte':'Account balance')+' '+balance[1];
 const spending=text.match(/^(?:Dépenses du compte|Spending from account) ([A-Z]{3})\. (?:Les opérations refusées,|Declined transactions,)$/);
 if(spending)return (target==='fr'?'Dépenses du compte ':'Spending from account ')+spending[1]+(target==='fr'?'. Les opérations refusées,':'. Declined transactions,');
 const newTransactions=text.match(/^(\d+) nouvelle(?:s opérations| opération)\.$/);
 if(newTransactions)return target==='fr'?text:newTransactions[1]+' new transaction'+(Number(newTransactions[1])===1?'':'s')+'.';
 if(target==='en'){
  if(text.startsWith('Région : '))return 'Region: '+text.slice(9);
  const balance=text.match(/^Indique un solde valide pour ([A-Z]{3}), entre 0 et 1 milliard\.$/);
  if(balance)return 'Enter a valid balance for '+balance[1]+', between 0 and 1 billion.';
  const minimum=text.match(/^Pour cet historique, le solde ([A-Z]{3}) doit être au moins (.+)\. Augmente le solde ou réduis les revenus du scénario\.$/);
  if(minimum)return 'For this history, the '+minimum[1]+' balance must be at least '+minimum[2]+'. Increase the balance or reduce scenario income.';
  const first=text.match(/^La première étape doit couvrir le début de l’historique : (.+)\.$/);
  if(first)return 'The first stop must cover the start of history: '+first[1]+'.';
 }
 return text;
}
const decode=text=>text.replace(/&(amp|lt|gt|quot|#39);/g,(_,name)=>({amp:'&',lt:'<',gt:'>',quot:'"','#39':"'"}[name]));
const escape=text=>text.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function textContent(text,lang){const match=text.match(/^(\s*)([\s\S]*?)(\s*)$/);const decoded=decode(match[2]),translated=tr(decoded,lang);return translated===decoded?text:match[1]+escape(translated)+match[3];}
// Translate system text and human-readable attributes only. IDs, form values,
// URLs, SVG paths and explicitly protected user content keep their exact bytes.
export function localizeHTML(html,lang=language){
 const stack=[];let protectedContent=false;
 return String(html).split(/(<(?:"[^"]*"|'[^']*'|[^'">])*>)/g).map(token=>{
  if(!token.startsWith('<'))return protectedContent?token:textContent(token,lang);
  const closing=token.match(/^<\/([a-z][\w:-]*)/i);
  if(closing){stack.pop();protectedContent=stack.at(-1)?.protected||false;return token;}
  const opening=token.match(/^<([a-z][\w:-]*)/i);if(!opening)return token;
  const name=opening[1].toLowerCase(),skip=protectedContent||/\bdata-i18n-skip(?:[\s=>])/.test(token)||['svg','script','style','textarea'].includes(name);
  const result=skip?token:token.replace(/(\b(?:aria-label|title|placeholder)=)(["'])(.*?)\2/g,(_,attr,quote,text)=>attr+quote+textContent(text,lang)+quote);
  if(!/\/\s*>$/.test(token)&&!['area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr'].includes(name)){stack.push({name,protected:skip});protectedContent=skip;}
  return result;
 }).join('');
}
